`),"src/cart.js":["import { priceFor } from './coupons.js'","","// The request path. Everything it needs is in memory by the time a request","// arrives, which is the whole reason p95 came down from 480ms to 11ms.","export function cartTotal(lines, coupon) {","  let total = 0","  for (const line of lines) {","    total += priceFor(line.sku, line.quantity, coupon)","  }","  return Math.round(total)","}","","export function cartBadge(lines) {","  return lines.reduce((count, line) => count + line.quantity, 0)","}",""].join(`
